let cols;
let rows;
let side = 100;

function setup(){
createCanvas(500, 500);
cols = width/side;
rows = height/side;
for(i = 0; i < cols; i ++){
  for(j = 0; j < rows; j ++){
  sqr(i, j);  

  }
}


}

