function sqr(x, y){
noStroke();
fill(255*sin(2*PI*x*y/(cols * rows))*sin(2*PI*x*y/(cols * rows)), 255*x/cols, 255*y/rows);
rect(x*side, y*side, side, side);
fill(255*cos(2*PI*x*y/(cols * rows))*cos(2*PI*x*y/(cols * rows)), 255*y/cols, 255*x/rows);
ellipse(x*side + side/2+ random(side/5), y*side + side/2 + random(side/5), 0.6*side, 0.6*side);

}

